function pad2(n){ return String(n).padStart(2,'0'); }
function parseHM(s){ var p=/^(\d{1,2}):(\d{2})$/.exec(s.trim()); if(!p) return null; var h=+p[1],m=+p[2]; if(h>23||m>59) return null; return h*60+m; }
function fmt(mins){ mins=((mins%1440)+1440)%1440; return pad2(Math.floor(mins/60))+':'+pad2(mins%60); }
function addMinutes(s, mins){ var t=parseHM(s); if(t===null) return null; return fmt(t+mins); }
function cyclesBetween(bed, wake){ var a=parseHM(bed), b=parseHM(wake); if(a===null||b===null) return null; var diff=(b-a+1440)%1440; return Math.floor(diff/90); }
function recommendedWake(bed, n){ n=n||5; return addMinutes(bed, n*90); }
var EXPORTS={parseHM:parseHM,fmt:fmt,addMinutes:addMinutes,cyclesBetween:cyclesBetween,recommendedWake:recommendedWake};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

